    /// A type step: font size and line height, in points.
    public struct TextStep: Sendable, Equatable {
        public let size: Double
        public let lineHeight: Double
    }

    public enum TypeScale {
        public static let meta = TextStep(size: 14, lineHeight: 20)
        public static let compact = TextStep(size: 16, lineHeight: 24)
        public static let control = TextStep(size: 14, lineHeight: 20)
        public static let post = TextStep(size: 18, lineHeight: 28)
        public static let title = TextStep(size: 20, lineHeight: 28)
        public static let heading = TextStep(size: 24, lineHeight: 30)
        public static let display = TextStep(size: 32, lineHeight: 40)
        public static let hero = TextStep(size: 48, lineHeight: 56)
    }

    /// Corner radii, in points. Pills use a capsule.
    public enum Radius {
        public static let xs: Double = 4
        public static let sm: Double = 6
        public static let md: Double = 8
        public static let lg: Double = 10
        public static let xl: Double = 14
    }

    /// Spacing and control heights, in points, at phone values.
    public enum Spacing {
        public static let inline: Double = 4
        public static let group: Double = 8
        public static let rowY: Double = 12
        public static let inset: Double = 16
        public static let page: Double = 16
        public static let section: Double = 24
        public static let controls: Double = 16
        public static let controlXs: Double = 28
        public static let controlSm: Double = 28
        public static let controlMd: Double = 32
        public static let controlLg: Double = 40
    }

    /// The smallest tap target, in points.
    public static let touchMinimum: Double = 44

    /// A cubic-bezier curve's control points.
    public struct Easing: Sendable, Equatable {
        public let x1: Double
        public let y1: Double
        public let x2: Double
        public let y2: Double
    }

    /// How things move (web: Foundations/Motion). Durations in seconds. `easeFade` is for a colour or opacity change,
    /// `easeMove` for anything that moves or changes size; nothing runs longer than `slow`.
    public enum Motion {
        public static let fast: Double = 0.1
        public static let moderate: Double = 0.15
        public static let slow: Double = 0.2
        public static let easeFade = Easing(x1: 0.2, y1: 0, x2: 0, y2: 1)
        public static let easeMove = Easing(x1: 0.22, y1: 1, x2: 0.36, y2: 1)
    }
}

#if canImport(SwiftUI) && canImport(UIKit)
import SwiftUI
import UIKit

public extension Color {
    /// An Avenue colour role that follows light and dark mode.
    static func avenue(_ role: KeyPath<AvenueTokens.Colors, UInt32>) -> Color {
        Color(uiColor: UIColor { traits in
            let hex = traits.userInterfaceStyle == .dark ? AvenueTokens.dark[keyPath: role] : AvenueTokens.light[keyPath: role]
            return UIColor(
                red: CGFloat((hex >> 16) & 0xFF) / 255,
                green: CGFloat((hex >> 8) & 0xFF) / 255,
                blue: CGFloat(hex & 0xFF) / 255,
                alpha: 1)
        })
    }
}

public extension Animation {
    /// An Avenue easing over a duration, like `.avenue(AvenueTokens.Motion.easeMove, duration: AvenueTokens.Motion.slow)`.
    static func avenue(_ easing: AvenueTokens.Easing, duration: Double) -> Animation {
        .timingCurve(easing.x1, easing.y1, easing.x2, easing.y2, duration: duration)
    }
}
#endif
